// 顶层模块
module top_module(
    input wire clk,           // 系统时钟
    input wire rst_n,         // 低电平复位
    input wire [7:0] data_in, // 8位输入数据
    output reg [7:0] data_out,// 8位输出数据
    output reg valid          // 输出有效标志
);

    // 内部寄存器
    reg [7:0] data_reg;
    reg [2:0] state;

    // 状态定义
    localparam IDLE = 3'b000;
    localparam PROC = 3'b001;
    localparam DONE = 3'b010;

    // 时序逻辑
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // 复位状态
            data_reg <= 8'b0;
            data_out <= 8'b0;
            valid <= 1'b0;
            state <= IDLE;
        end
        else begin
            case (state)
                IDLE: begin
                    valid <= 1'b0;
                    if (data_in != 8'b0) begin
                        data_reg <= data_in;
                        state <= PROC;
                    end
                end

                PROC: begin
                    // 示例处理：数据加1
                    data_out <= data_reg + 8'b1;
                    state <= DONE;
                end

                DONE: begin
                    valid <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

