module fifo_sync #(
    parameter WIDTH = 8,
    parameter DEPTH = 16,
    parameter AW    = $clog2(DEPTH)
)(
    input  wire              clk,
    input  wire              rst,
    input  wire              wr_en,
    input  wire              rd_en,
    input  wire [WIDTH-1:0]  din,
    output reg  [WIDTH-1:0]  dout,
    output wire              empty,
    output wire              full
);
    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [AW:0] wptr, rptr; // extra bit for full/empty
    assign empty = (wptr == rptr);
    assign full  = (wptr[AW] != rptr[AW]) && (wptr[AW-1:0] == rptr[AW-1:0]);
    always @(posedge clk) begin
        if (rst) begin
            wptr <= 0; rptr <= 0; dout <= {WIDTH{1'b0}};
        end else begin
            if (wr_en && !full) begin
                mem[wptr[AW-1:0]] <= din;
                wptr <= wptr + 1'b1;
            end
            if (rd_en && !empty) begin
                dout <= mem[rptr[AW-1:0]];
                rptr <= rptr + 1'b1;
            end
        end
    end
endmodule

