module fsm_template #(
    parameter STATE_BITS = 3,
    parameter OUT_BITS = 4
)(
    input  wire                   clk,
    input  wire                   rst,
    input  wire [3:0]             inputs,
    output reg  [OUT_BITS-1:0]    outputs,
    output reg  [STATE_BITS-1:0]  current_state
);
    // State definitions
    localparam IDLE   = 3'b000;
    localparam STATE1 = 3'b001;
    localparam STATE2 = 3'b010;
    localparam STATE3 = 3'b011;

    reg [STATE_BITS-1:0] next_state;

    // State register (sequential)
    always @(posedge clk or posedge rst) begin
        if (rst) current_state <= IDLE;
        else     current_state <= next_state;
    end

    // Next state logic (combinational)
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (inputs[0]) next_state = STATE1;
                else           next_state = IDLE;
            end
            STATE1: begin
                if (inputs[1]) next_state = STATE2;
                else           next_state = IDLE;
            end
            STATE2: begin
                if (inputs[2]) next_state = STATE3;
                else           next_state = IDLE;
            end
            STATE3: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // Output logic (combinational)
    always @(*) begin
        case (current_state)
            IDLE:   outputs = 4'b0000;
            STATE1: outputs = 4'b0001;
            STATE2: outputs = 4'b0011;
            STATE3: outputs = 4'b0111;
            default: outputs = 4'b0000;
        endcase
    end
endmodule

module pwm_generator #(
