module uart_tx #(
    parameter CLK_FREQ = 50_000_000,
    parameter BAUD_RATE = 9600
)(
    input  wire       clk,
    input  wire       rst,
    input  wire       tx_start,
    input  wire [7:0] tx_data,
    output reg        tx,
    output reg        tx_busy
);
    localparam BAUD_DIV = CLK_FREQ / BAUD_RATE;
    localparam DIV_BITS = $clog2(BAUD_DIV);

    reg [DIV_BITS-1:0] baud_counter;
    reg [3:0] bit_counter;
    reg [9:0] shift_reg;

    typedef enum reg [1:0] {
        IDLE = 2'b00,
        START = 2'b01,
        DATA = 2'b10,
        STOP = 2'b11
    } state_t;

    state_t state;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            tx <= 1'b1;
            tx_busy <= 1'b0;
            baud_counter <= 0;
            bit_counter <= 0;
            shift_reg <= 10'h3FF;
        end else begin
            case (state)
                IDLE: begin
                    tx <= 1'b1;
                    tx_busy <= 1'b0;
                    if (tx_start) begin
                        shift_reg <= {1'b1, tx_data, 1'b0};
                        state <= START;
                        tx_busy <= 1'b1;
                        baud_counter <= 0;
                        bit_counter <= 0;
                    end
                end

                START, DATA, STOP: begin
                    if (baud_counter == BAUD_DIV - 1) begin
                        baud_counter <= 0;
                        tx <= shift_reg[0];
                        shift_reg <= {1'b1, shift_reg[9:1]};

                        if (bit_counter == 9) begin
                            state <= IDLE;
                        end else begin
                            bit_counter <= bit_counter + 1'b1;
                            state <= DATA;
                        end
                    end else begin
                        baud_counter <= baud_counter + 1'b1;
                    end
                end
            endcase
        end
    end
endmodule

module spi_master #(
    parameter CLK_DIV = 4
)(
    input  wire       clk,
    input  wire       rst,
    input  wire       start,
    input  wire       miso,
    input  wire [7:0] tx_data,
    output reg        sclk,
    output reg        mosi,
    output reg        cs_n,
    output reg  [7:0] rx_data,
    output reg        done
);
    reg [2:0] clk_counter;
    reg [3:0] bit_counter;
    reg [7:0] tx_shift, rx_shift;
    reg active;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sclk <= 1'b0;
            mosi <= 1'b0;
            cs_n <= 1'b1;
            rx_data <= 8'h00;
            done <= 1'b0;
            clk_counter <= 0;
            bit_counter <= 0;
            tx_shift <= 8'h00;
            rx_shift <= 8'h00;
            active <= 1'b0;
        end else begin
            done <= 1'b0;

            if (start && !active) begin
                active <= 1'b1;
                cs_n <= 1'b0;
                tx_shift <= tx_data;
                bit_counter <= 0;
                clk_counter <= 0;
                sclk <= 1'b0;
            end else if (active) begin
                clk_counter <= clk_counter + 1'b1;

                if (clk_counter == CLK_DIV/2 - 1) begin
                    sclk <= 1'b1;
                    mosi <= tx_shift[7];
                end else if (clk_counter == CLK_DIV - 1) begin
                    sclk <= 1'b0;
                    clk_counter <= 0;
                    rx_shift <= {rx_shift[6:0], miso};
                    tx_shift <= {tx_shift[6:0], 1'b0};
                    bit_counter <= bit_counter + 1'b1;

                    if (bit_counter == 7) begin
                        active <= 1'b0;
                        cs_n <= 1'b1;
                        rx_data <= {rx_shift[6:0], miso};
                        done <= 1'b1;
                    end
                end
            end
        end
    end
endmodule

module button_debounce #(
    parameter DEBOUNCE_TIME = 1000000  // 20ms at 50MHz
)(
    input  wire clk,
    input  wire rst,
    input  wire button_in,
    output reg  button_out
);
    localparam COUNTER_BITS = $clog2(DEBOUNCE_TIME);

    reg [COUNTER_BITS-1:0] counter;
    reg button_sync1, button_sync2;

    // Synchronize input
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            button_sync1 <= 1'b0;
            button_sync2 <= 1'b0;
        end else begin
            button_sync1 <= button_in;
            button_sync2 <= button_sync1;
        end
    end

    // Debounce logic
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 0;
            button_out <= 1'b0;
        end else begin
            if (button_sync2 == button_out) begin
                counter <= 0;
            end else begin
                counter <= counter + 1'b1;
                if (counter == DEBOUNCE_TIME - 1) begin
                    button_out <= button_sync2;
                    counter <= 0;
                end
            end
        end
    end
endmodule

module crc8_generator #(
    parameter POLYNOMIAL = 8'h07  // CRC-8 polynomial
)(
    input  wire       clk,
    input  wire       rst,
    input  wire [7:0] data_in,
    input  wire       data_valid,
    output reg  [7:0] crc_out
);
    integer i;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            crc_out <= 8'h00;
        end else if (data_valid) begin
            crc_out <= crc_out ^ data_in;
            for (i = 0; i < 8; i = i + 1) begin
                if (crc_out[7])
                    crc_out <= (crc_out << 1) ^ POLYNOMIAL;
                else
                    crc_out <= crc_out << 1;
            end
        end
    end
endmodule

module data_width_converter_8to16(
    input  wire       clk,
    input  wire       rst,
    input  wire [7:0] data_in,
    input  wire       data_valid,
    output reg [15:0] data_out,
    output reg        data_out_valid
);
    reg [7:0] data_reg;
    reg byte_select;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            data_reg <= 8'b0;
            data_out <= 16'b0;
            data_out_valid <= 1'b0;
            byte_select <= 1'b0;
        end else begin
            data_out_valid <= 1'b0;

            if (data_valid) begin
                if (!byte_select) begin
                    data_reg <= data_in;
                    byte_select <= 1'b1;
                end else begin
                    data_out <= {data_in, data_reg};
                    data_out_valid <= 1'b1;
                    byte_select <= 1'b0;
                end
            end
        end
    end
endmodule

module serial_to_parallel #(
    parameter WIDTH = 8
)(
    input  wire              clk,
    input  wire              rst,
    input  wire              serial_in,
    input  wire              load,
    output reg [WIDTH-1:0]   parallel_out,
    output reg               done
);
    reg [WIDTH-1:0] shift_reg;
    reg [$clog2(WIDTH)-1:0] bit_counter;
    reg loading;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            shift_reg <= {WIDTH{1'b0}};
            parallel_out <= {WIDTH{1'b0}};
            bit_counter <= 0;
            loading <= 1'b0;
            done <= 1'b0;
        end else begin
            done <= 1'b0;

            if (load && !loading) begin
                loading <= 1'b1;
                bit_counter <= 0;
                shift_reg <= {WIDTH{1'b0}};
            end else if (loading) begin
                shift_reg <= {shift_reg[WIDTH-2:0], serial_in};
                bit_counter <= bit_counter + 1'b1;

                if (bit_counter == WIDTH - 1) begin
                    parallel_out <= {shift_reg[WIDTH-2:0], serial_in};
                    loading <= 1'b0;
                    done <= 1'b1;
                end
            end
        end
    end
endmodule

module crc16_modbus(
    input  wire       clk,
    input  wire       rst,
    input  wire [7:0] data_in,
    input  wire       data_valid,
    output reg [15:0] crc_out
);
    integer i;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            crc_out <= 16'hFFFF;
        end else if (data_valid) begin
            crc_out <= crc_out ^ data_in;
            for (i=0; i<8; i=i+1) begin
                if (crc_out[0])
                    crc_out <= (crc_out >> 1) ^ 16'hA001;
                else
                    crc_out <= (crc_out >> 1);
            end
        end
    end
endmodule

module crc32_ieee(
    input  wire       clk,
    input  wire       rst,
    input  wire [7:0] data_in,
    input  wire       data_valid,
    output reg [31:0] crc_out
);
    integer i;
    reg [31:0] x;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            crc_out <= 32'hFFFF_FFFF;
        end else if (data_valid) begin
            x = (crc_out ^ data_in) & 32'hFF;
            for (i=0; i<8; i=i+1) begin
                if (x[0]) x = (x >> 1) ^ 32'hEDB88320;
                else      x = x >> 1;
            end
            crc_out <= (crc_out >> 8) ^ x;
        end
    end
    always @(*) begin
        // 若需要最终值，可在外部对 crc_out ^ 32'hFFFF_FFFF 取反
    end
endmodule

