module lrc8_acc(
    input  wire       clk,
    input  wire       rst,
    input  wire [7:0] data_in,
    input  wire       data_valid,
    output reg  [7:0] lrc
);
    reg [7:0] sum;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sum <= 8'h00;
            lrc <= 8'h00;
        end else if (data_valid) begin
            sum <= sum + data_in;
            lrc <= (-sum) & 8'hFF;
        end
    end
endmodule
